package org.slavicmyths.gorynych;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.projectile.*;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;
import net.minecraft.world.effect.*;
import net.minecraft.tags.DamageTypeTags;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.entity.living.*;
@EventBusSubscriber(modid="slavicmyths")
public final class GorynychEquipment {
 private static final ThreadLocal<Boolean> SECONDARY=ThreadLocal.withInitial(()->false);
 public static boolean worn(LivingEntity e,EquipmentSlot slot){return e.getItemBySlot(slot).is(GorynychContent.ARMOR.get(slot).get());}
 public static boolean supports(ItemStack s,String id){String category=org.slavicmyths.rpg.Runes.category(s);return switch(id){case "mor_breath"->Set.of("sword","dagger","spear","heavy","staff","whip").contains(category);case "dragon_flame"->Set.of("sword","dagger","spear","heavy","whip").contains(category);case "storm_strike"->category.equals("bow");default->false;};}
 @SubscribeEvent public static void damage(LivingDamageEvent.Pre e){if(e.getEntity().level().isClientSide)return;var target=e.getEntity();if(worn(target,EquipmentSlot.CHEST)&&(e.getSource().is(DamageTypeTags.IS_FIRE)||e.getSource().is(DamageTypeTags.IS_EXPLOSION)))e.setNewDamage(e.getNewDamage()*.85f);if(worn(target,EquipmentSlot.FEET)&&e.getSource().is(net.minecraft.world.damagesource.DamageTypes.FALL))e.setNewDamage(e.getNewDamage()*.65f);}
 @SubscribeEvent public static void knock(LivingKnockBackEvent e){if(!e.getEntity().level().isClientSide&&worn(e.getEntity(),EquipmentSlot.LEGS))e.setStrength(e.getStrength()*.7f);}
 @SubscribeEvent public static void effect(MobEffectEvent.Added e){var effect=e.getEffectInstance();if(!e.getEntity().level().isClientSide&&worn(e.getEntity(),EquipmentSlot.HEAD)&&!effect.isInfiniteDuration()&&(effect.is(MobEffects.BLINDNESS)||effect.is(MobEffects.DARKNESS)||effect.is(MobEffects.CONFUSION)))((org.slavicmyths.equipment.mixin.GorynychEffectDuration)effect).slavicmyths$gorynychDuration(Math.max(1,(int)(effect.getDuration()*.75)));}
 @SubscribeEvent public static void player(net.neoforged.neoforge.event.tick.PlayerTickEvent.Post e){if(!(e.getEntity() instanceof ServerPlayer p)||p.tickCount%20!=0||!p.isAlive())return;var n=GorynychLedger.part(org.slavicmyths.rpg.PathData.data(p),"GorynychEquipment");long now=p.serverLevel().getGameTime();if(p.getHealth()<p.getMaxHealth()*.3&&GorynychContent.ARMOR.keySet().stream().allMatch(s->worn(p,s))&&now>=n.getLong("StandReady")){n.putLong("StandReady",now+3600);p.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE,100,0));GorynychContent.sound(p.level(),p.blockPosition(),"armor_fullset_proc");}}
 @SubscribeEvent public static void hit(LivingDamageEvent.Post e){if(e.getEntity().level().isClientSide||e.getNewDamage()<=0||SECONDARY.get()||e.getSource().getDirectEntity()==null)return;var from=e.getSource().getEntity();if(!(from instanceof LivingEntity owner)||!BreathCloud.allowed(owner,e.getEntity()))return;ItemStack weapon=owner.getMainHandItem();boolean ranged=e.getSource().getDirectEntity() instanceof Projectile;if(e.getSource().getDirectEntity() instanceof AbstractArrow arrow&&arrow.getWeaponItem()!=null)weapon=arrow.getWeaponItem();var n=GorynychLedger.part(owner instanceof ServerPlayer p?org.slavicmyths.rpg.PathData.data(p):owner.getPersistentData(),"GorynychRuneCounters");for(String rune:GorynychContent.RUNES){if(!supports(weapon,rune)||!org.slavicmyths.rpg.Runes.has(weapon,rune)||(rune.equals("storm_strike")?!ranged:ranged&&!org.slavicmyths.rpg.Runes.category(weapon).equals("staff")))continue;int threshold=rune.equals("mor_breath")?5:4;int count=n.getInt(rune)+1;n.putInt(rune,count%threshold);if(count%threshold==0)burst(owner,e.getEntity().position(),rune.equals("mor_breath")?0:rune.equals("dragon_flame")?1:2,rune.equals("mor_breath")?2:3,e.getEntity());}}
 @SubscribeEvent public static void impact(net.neoforged.neoforge.event.entity.ProjectileImpactEvent e){var shot=e.getProjectile();int mode=shot.getPersistentData().getInt("GorynychSpecial");if(mode<1||mode>3||!(shot.getOwner() instanceof LivingEntity owner)||owner.level().isClientSide)return;shot.getPersistentData().remove("GorynychSpecial");burst(owner,e.getRayTraceResult().getLocation(),mode-1,3);}
 public static void burst(LivingEntity owner,Vec3 at,int type,double radius){burst(owner,at,type,radius,null);}
 private static void burst(LivingEntity owner,Vec3 at,int type,double radius,LivingEntity excluded){if(!(owner.level() instanceof ServerLevel w))return;SECONDARY.set(true);try{if(type==0){var cloud=GorynychContent.CLOUD.get().create(w);if(cloud!=null){cloud.configure(owner,0,at,3);w.addFreshEntity(cloud);}return;}for(var target:w.getEntitiesOfClass(LivingEntity.class,new AABB(at.subtract(radius,radius,radius),at.add(radius,radius,radius)),t->t!=excluded&&BreathCloud.allowed(owner,t)&&t.position().distanceToSqr(at)<=radius*radius)){if(w.clip(new net.minecraft.world.level.ClipContext(at.add(0,.5,0),target.getEyePosition(),net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,owner)).getType()!=HitResult.Type.MISS)continue;if(type==1){target.hurt(org.slavicmyths.combat.MythDamageSources.periodic("gorynych_fire",owner),5);target.igniteForSeconds(2);}else{var delta=target.position().subtract(at).normalize().scale(.65);target.setDeltaMovement(target.getDeltaMovement().add(delta.x,.2,delta.z));target.hurtMarked=true;if(target instanceof Mob mob&&!(mob instanceof Gorynych)){mob.getNavigation().stop();mob.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,20,2));}}}w.sendParticles(BreathCloud.particle(type),at.x,at.y+.3,at.z,36,radius,.4,radius,.04);}finally{SECONDARY.set(false);}}
 @SubscribeEvent public static void struggle(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickItem e){if(e.getEntity() instanceof ServerPlayer p)escape(p);}
 @SubscribeEvent public static void block(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock e){if(e.getEntity() instanceof ServerPlayer p)escape(p);}
 @SubscribeEvent public static void left(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.LeftClickBlock e){if(e.getEntity() instanceof ServerPlayer p)escape(p);}
 @SubscribeEvent public static void attack(net.neoforged.neoforge.event.entity.player.AttackEntityEvent e){if(e.getEntity() instanceof ServerPlayer p)escape(p);}
 private static void escape(ServerPlayer p){for(var boss:p.serverLevel().getEntitiesOfClass(Gorynych.class,p.getBoundingBox().inflate(16),b->b.grabbed(p)))boss.resistGrab();}
 private GorynychEquipment(){}
}
